# validate anti-diagonal span algorithm on both demos

def spanfill(arr, fg, fill=2):
 out=arr.copy(); R,C=arr.shape
 for u in range(R+C-1):
  pts=[(r,u-r) for r in range(R) if 0<=u-r<C and arr[r,u-r]==fg]
  if len(pts)>=2:
   r0=min(r for r,c in pts); r1=max(r for r,c in pts)
   for r in range(r0,r1+1):
    c=u-r
    if arr[r,c]!=fg: out[r,c]=fill
 return out
print('demo1 match?', np.array_equal(spanfill(a,3),b), 'mismatches',np.argwhere(spanfill(a,3)!=b)[:30])

def diag_segments(arr,fg):
    R,C=arr.shape
    by_d={}
    for r in range(R):
        for c in range(C):
            if arr[r,c]==fg:
                d=c-r; by_d.setdefault(d,[]).append(r)
    segs=[]
    for d,rs in sorted(by_d.items()):
        rs=sorted(rs)
        runs=[]
        for r in rs:
            if not runs or r>runs[-1][-1]+1: runs.append([r])
            else:runs[-1].append(r)
        for run in runs:
            us=[2*r+d for r in run] # r+c = 2r+d
            segs.append((d,min(us),max(us),run))
    return segs

def fill_strips(arr,fg,fill=2):
    out=arr.copy(); R,C=arr.shape
    segs=diag_segments(arr,fg)
    # for each integer u, active segments in interval, fill grid cells between outer active d values
    for r in range(R):
      for c in range(C):
        if arr[r,c]==fg: continue
        u=r+c; d=c-r
        active=[d0 for d0,u0,u1,_ in segs if u0<=u<=u1]
        # Need distinct strokes, not merely duplicate segments same d
        active=sorted(set(active))
        if len(active)>=2 and min(active)<=d<=max(active):
          out[r,c]=fill
    return out

